const encoder = new TextEncoder();
function sseEvent(obj: object): Uint8Array {
  return encoder.encode(`data: ${JSON.stringify(obj)}\n\n`);
}

// ── Key management ─────────────────────────────────────────────────

async function decryptApiKey(encryptedKey: string): Promise<string> {
  const encryptionKeyHex = Deno.env.get("ENCRYPTION_KEY");
  if (!encryptionKeyHex) throw new Error("ENCRYPTION_KEY not configured");
  const keyBytes = new Uint8Array(
    encryptionKeyHex.match(/.{1,2}/g)!.map((byte: string) => parseInt(byte, 16))
  );
  const encryptedData = Uint8Array.from(atob(encryptedKey), (c: string) => c.charCodeAt(0));
  const iv = encryptedData.slice(0, 12);
  const ciphertext = encryptedData.slice(12);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: "AES-GCM" }, false, ["decrypt"]);
  const decrypted = await crypto.subtle.decrypt({ name: "AES-GCM", iv }, key, ciphertext);
  return new TextDecoder().decode(decrypted);
}

async function getApiKey(supabase: any, organizationId: string, provider: string): Promise<string | null> {
  // Try org-specific encrypted key first
  const { data, error } = await supabase
    .from("api_keys")
    .select("key_encrypted")
    .eq("organization_id", organizationId)
    .eq("provider", provider)
    .limit(1);
  if (!error && data?.length) {
    try {
      return await decryptApiKey(data[0].key_encrypted);
    } catch (e) {
      console.error(`Failed to decrypt ${provider} key:`, e);
    }
  }
  // Fall back to environment variable (e.g. PEXELS_API_KEY, PIXABAY_API_KEY)
  const envName = `${provider.toUpperCase()}_API_KEY`;
  return Deno.env.get(envName) || null;
}

